package com.example.com.englishai.backend.infrastructure.persistence.repository; import org.springframework.stereotype.Repository; import com.example.com.englishai.backend.application.ports.PasswordResetCodeRepository; import com.example.com.englishai.backend.domain.authentication.PasswordResetCode; import com.example.com.englishai.backend.infrastructure.persistence.mapper.PasswordResetCodeMapper; import java.util.*;
@Repository public class PasswordResetCodeRepositoryAdapter implements PasswordResetCodeRepository {private final PasswordResetCodeJpaRepository r;private final PasswordResetCodeMapper m;public PasswordResetCodeRepositoryAdapter(PasswordResetCodeJpaRepository r,PasswordResetCodeMapper m){this.r=r;this.m=m;}public PasswordResetCode save(PasswordResetCode c){return m.toDomain(r.save(m.toEntity(c)));}public List<PasswordResetCode> findByUserIdForUpdate(UUID id){return r.findByUserIdOrderByCreatedAtDesc(id).stream().map(m::toDomain).toList();}}
